/** Native user-scoped CRM. No customer fixtures or passwords are persisted. */
public class MainActivity extends Activity {
    final ClickToCall clickToCall=new ClickToCall(this);
    @Override protected void onResume(){super.onResume();clickToCall.resume();}
    @Override protected void onPause(){clickToCall.pause();super.onPause();}
    static final int PURPLE=0xff5034a3,INK=0xff242231,MUTED=0xff737080,BG=0xfff4f3f8;
    LinearLayout root,content;TextView syncStatus;String screen="Home",filter="All",search="",pendingCall;JSONObject workspace=new JSONObject();boolean busy;MediaPlayer player;
    final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());
    final Runnable update=new Runnable(){public void run(){if(syncStatus!=null)syncStatus.setText(SecureConfig.prefs(MainActivity.this).getString("status","Not yet synced."));handler.postDelayed(this,3000);}};
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    TextView text(LinearLayout b,String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(INK);t.setPadding(0,dp(5),0,dp(5));if(bold)t.setTypeface(null,Typeface.BOLD);b.addView(t);return t;}
    void caption(LinearLayout b,String s){text(b,s,13,false).setTextColor(MUTED);}
    LinearLayout card(){LinearLayout c=column();c.setPadding(dp(16),dp(12),dp(16),dp(12));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(10));c.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));content.addView(c,p);return c;}
    EditText input(LinearLayout b,String label,String value){caption(b,label);EditText e=new EditText(this);e.setText(value);e.setSingleLine();e.setTextSize(15);b.addView(e);return e;}
    void button(LinearLayout b,String title,Runnable action){Button v=new Button(this);v.setText(title);v.setAllCaps(false);v.setTextColor(PURPLE);b.addView(v);v.setOnClickListener(w->{try{action.run();}catch(Exception e){notice("Action failed. "+e.getMessage());}});}
    void notice(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("OK",null).show();}
    JSONArray rows(String key){JSONArray a=workspace.optJSONArray(key);return a==null?new JSONArray():a;}
    String leadName(String id){for(int i=0;i<rows("leads").length();i++){JSONObject l=rows("leads").optJSONObject(i);if(l!=null&&l.optString("id").equals(id))return l.optString("name");}return "Business contact";}
    String phoneName(String number){String country=SecureConfig.prefs(this).getString("country","91"),n=SyncEngine.normalize(number,country);for(int i=0;i<rows("leads").length();i++){JSONObject l=rows("leads").optJSONObject(i);if(l!=null&&SyncEngine.normalize(l.optString("phone"),country).equals(n))return l.optString("name");}return "Assigned business contact";}
    void work(Runnable task){if(busy){notice("Please wait for the current request.");return;}busy=true;new Thread(()->{try{task.run();}finally{runOnUiThread(()->busy=false);}}).start();}
    void failure(Exception e){runOnUiThread(()->{if(e instanceof SyncEngine.HttpError&&(((SyncEngine.HttpError)e).code==401||((SyncEngine.HttpError)e).code==403)){SyncJob.schedule(this,false);SecureConfig.prefs(this).edit().putBoolean("enabled",false).commit();notice("Session expired or access denied. Sign out and sign in again. Sync is paused.");}else notice("Request failed. Check connection and server. "+e.getMessage());});}
    @Override public void onCreate(Bundle state){super.onCreate(state);if(!BuildConfig.CRM_API_ORIGIN.equals(SecureConfig.prefs(this).getString("endpoint",""))){if(SecureConfig.loggedIn(this))SecureConfig.logout(this);SecureConfig.prefs(this).edit().putString("endpoint",BuildConfig.CRM_API_ORIGIN).commit();}if(!BuildConfig.DEBUG)getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);getWindow().setStatusBarColor(PURPLE);getWindow().setNavigationBarColor(Color.WHITE);if(state!=null)pendingCall=state.getString("pending");try{workspace=new JSONObject(SecureConfig.prefs(this).getString("workspace","{}"));}catch(Exception ignored){}render();handler.post(update);if(SecureConfig.loggedIn(this))refresh();}
    void render(){syncStatus=null;root=column();root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,insets)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();if(!SecureConfig.loggedIn(this)){login();return;}
        LinearLayout bar=new LinearLayout(this);bar.setPadding(dp(18),dp(12),dp(12),dp(10));bar.setBackgroundColor(Color.WHITE);TextView title=new TextView(this);title.setText("Salesdesk / "+screen);title.setTextSize(21);title.setTextColor(PURPLE);title.setTypeface(null,Typeface.BOLD);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));ImageButton refresh=new ImageButton(this);refresh.setImageResource(android.R.drawable.ic_popup_sync);refresh.setContentDescription("Refresh workspace");refresh.setBackgroundColor(Color.TRANSPARENT);bar.addView(refresh,new LinearLayout.LayoutParams(dp(44),dp(44)));refresh.setOnClickListener(v->refresh());root.addView(bar);
        ScrollView scroll=new ScrollView(this);content=column();content.setPadding(dp(14),dp(14),dp(14),dp(14));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(screen.equals("Home"))home();else if(screen.equals("Leads"))leads();else if(screen.equals("Calls"))calls();else if(screen.equals("Tasks"))tasks();else {clickToCall.settings(card());settings();}
        LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(Color.WHITE);String[] names={"Home","Leads","Calls","Tasks","Settings"};int[] icons={android.R.drawable.ic_menu_view,android.R.drawable.ic_menu_myplaces,android.R.drawable.ic_menu_call,android.R.drawable.ic_menu_agenda,android.R.drawable.ic_menu_preferences};for(int i=0;i<names.length;i++){final String target=names[i];LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setPadding(0,dp(8),0,dp(8));ImageView icon=new ImageView(this);icon.setImageResource(icons[i]);icon.setColorFilter(screen.equals(target)?PURPLE:MUTED);item.addView(icon,new LinearLayout.LayoutParams(dp(24),dp(24)));text(item,target,11,screen.equals(target)).setTextColor(screen.equals(target)?PURPLE:MUTED);nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));item.setOnClickListener(v->{screen=target;render();});}root.addView(nav);
    }
    void login(){
        ScrollView scroll=new ScrollView(this);LinearLayout b=column();b.setPadding(dp(26),dp(48),dp(26),dp(24));scroll.addView(b);root.addView(scroll);
        text(b,"Salesdesk",32,true).setTextColor(PURPLE);text(b,"Sign in to your company CRM",18,false);
        caption(b,"Use the same username and password as web CRM. Your company connection is already configured — no IP address or server link needed.");
        EditText user=input(b,"Username",""),password=input(b,"Password","");user.setInputType(33);password.setInputType(129);
        button(b,"Sign in",()->{
            String username=user.getText().toString().trim(),secret=password.getText().toString();if(username.isEmpty()||secret.isEmpty()){notice("Enter your CRM username and password.");return;}password.setText("");
            SecureConfig.prefs(this).edit().putString("endpoint",BuildConfig.CRM_API_ORIGIN).commit();
            work(()->{try{JSONObject r=SyncEngine.requestApi(this,"/v1/login","POST",new JSONObject().put("username",username).put("password",secret).put("deviceId",SecureConfig.deviceId(this)));JSONObject a=r.getJSONObject("user");SecureConfig.token(this,r.getString("token"));SecureConfig.prefs(this).edit().putString("userId",a.getString("id")).putString("user",a.toString()).remove("workspace").remove("targets").putLong("since",System.currentTimeMillis()).putBoolean("enabled",false).putBoolean("clickToCall",false).putBoolean("callWhileLocked",false).commit();workspace=new JSONObject();runOnUiThread(this::render);loadWorkspace();}catch(Exception e){runOnUiThread(()->notice(e instanceof SyncEngine.HttpError?(((SyncEngine.HttpError)e).code==401?"Username or password is incorrect. Use the account created in web CRM.":"Company CRM is not ready or access was refused. Contact your administrator."):"Cannot reach your company CRM. Check your internet connection and try again."));}});
        });caption(b,"Password is never saved. Business call sync and background calling stay off until you enable them in Settings.");
    }
    void refresh(){work(()->{try{loadWorkspace();}catch(Exception e){failure(e);}});}
    void loadWorkspace()throws Exception{JSONObject d=SyncEngine.requestApi(this,"/v1/workspace","GET",null);SecureConfig.prefs(this).edit().putString("workspace",d.toString()).putLong("workspaceAt",System.currentTimeMillis()).commit();workspace=d;runOnUiThread(this::render);}
    void home(){JSONObject user=workspace.optJSONObject("user");if(user==null)try{user=new JSONObject(SecureConfig.prefs(this).getString("user","{}"));}catch(Exception ignored){}LinearLayout c=card();text(c,"Hello, "+(user==null?"":user.optString("name")),23,true);caption(c,user==null?"":user.optString("role"));text(c,rows("leads").length()+" leads  ·  "+rows("tasks").length()+" tasks",17,true);long at=SecureConfig.prefs(this).getLong("workspaceAt",0);caption(c,at==0?"Refresh to load your workspace.":"Cached workspace · "+new Date(at));text(content,"Recent activity",19,true);JSONArray a=rows("activities");if(a.length()==0)caption(content,"No activity in your workspace yet.");for(int i=a.length()-1;i>=Math.max(0,a.length()-20);i--){JSONObject r=a.optJSONObject(i);if(r==null)continue;LinearLayout entry=card();text(entry,leadName(r.optString("leadId")),16,true);text(entry,r.optString("text",r.optString("title",r.optString("type","Activity"))),14,false);caption(entry,r.optString("createdAt",r.optString("date")));}}
    interface Payload{JSONObject get()throws Exception;}
    void mutate(String path,String method,Payload payload){work(()->{try{SyncEngine.requestApi(this,path,method,payload.get());loadWorkspace();}catch(Exception e){failure(e);}});}
    void leads(){button(content,"Add lead",this::leadForm);EditText query=input(content,"Search assigned leads",search);button(content,"Search",()->{search=query.getText().toString();render();});int shown=0;for(int i=0;i<rows("leads").length();i++){JSONObject l=rows("leads").optJSONObject(i);if(l==null||!l.toString().toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT)))continue;shown++;LinearLayout c=card();text(c,l.optString("name"),18,true);caption(c,l.optString("phone")+" · "+l.optString("company"));text(c,l.optString("stage","New"),13,true).setTextColor(PURPLE);c.setOnClickListener(v->leadDetail(l));}if(shown==0)caption(content,"No matching leads. Refresh or add a lead.");}
    void leadForm(){LinearLayout b=column();b.setPadding(dp(20),0,dp(20),0);EditText name=input(b,"Name",""),phone=input(b,"Phone",""),company=input(b,"Company","");phone.setInputType(3);new AlertDialog.Builder(this).setTitle("New lead").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->mutate("/v1/leads","POST",()->new JSONObject().put("name",name.getText().toString()).put("phone",phone.getText().toString()).put("company",company.getText().toString()))).show();}
    void leadDetail(JSONObject l){LinearLayout b=column();b.setPadding(dp(20),0,dp(20),0);text(b,l.optString("phone"),16,false);caption(b,l.optString("email")+" · "+l.optString("company"));button(b,"Change stage",()->{String[] stages={"New","Prospecting","Opportunity","Closed"};new AlertDialog.Builder(this).setTitle("Lead stage").setItems(stages,(d,w)->mutate("/v1/leads/"+l.optString("id"),"PATCH",()->new JSONObject().put("stage",stages[w]))).show();});button(b,"Add note",()->{EditText note=new EditText(this);note.setHint("Your note");new AlertDialog.Builder(this).setTitle("Add note").setView(note).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->mutate("/v1/notes","POST",()->new JSONObject().put("leadId",l.optString("id")).put("text",note.getText().toString()))).show();});button(b,"Open dialer",()->new AlertDialog.Builder(this).setMessage("Open this number in the dialer? No call is placed automatically.").setNegativeButton("Cancel",null).setPositiveButton("Open dialer",(d,w)->startActivity(new Intent(Intent.ACTION_DIAL,Uri.fromParts("tel",l.optString("phone"),null)))).show());new AlertDialog.Builder(this).setTitle(l.optString("name")).setView(b).setPositiveButton("Close",null).show();}
    void tasks(){button(content,"Add task",()->{LinearLayout b=column();b.setPadding(dp(20),0,dp(20),0);EditText title=input(b,"Task title",""),due=input(b,"Due (ISO, e.g. 2026-10-23T09:00:00Z)","");new AlertDialog.Builder(this).setTitle("New task").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->mutate("/v1/tasks","POST",()->new JSONObject().put("title",title.getText().toString()).put("due",due.getText().toString()))).show();});if(rows("tasks").length()==0)caption(content,"No assigned tasks yet.");for(int i=0;i<rows("tasks").length();i++){JSONObject t=rows("tasks").optJSONObject(i);if(t==null)continue;LinearLayout c=card();text(c,t.optString("title"),17,true);caption(c,t.optString("due")+" · "+t.optString("status","Open"));button(c,t.optString("status").equals("Done")?"Reopen":"Mark done",()->mutate("/v1/tasks/"+t.optString("id"),"PATCH",()->new JSONObject().put("status",t.optString("status").equals("Done")?"Open":"Done")));}}
    void calls(){LinearLayout tabs=new LinearLayout(this);for(String f:new String[]{"All","Incoming","Outgoing","Missed"}){Button b=new Button(this);b.setText(f);b.setTextSize(11);b.setAllCaps(false);b.setTextColor(f.equals(filter)?PURPLE:MUTED);tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{filter=f;render();});}content.addView(tabs);button(content,"Sync business calls",this::sync);caption(content,"Only calls matching assigned CRM leads are collected. Personal calls are excluded.");Set<String> ids=new HashSet<>();int count=0;try(QueueDb db=new QueueDb(this);Cursor cur=db.getReadableDatabase().rawQuery("SELECT * FROM calls ORDER BY started DESC LIMIT 500",null)){while(cur.moveToNext()){JSONObject r=new JSONObject();for(String k:cur.getColumnNames())r.put(k,cur.isNull(cur.getColumnIndexOrThrow(k))?"":cur.getString(cur.getColumnIndexOrThrow(k)));ids.add(r.optString("remote_id"));if(!filter.equals("All")&&!filter.equals(r.optString("direction")))continue;callCard(r,true);count++;}}catch(Exception e){caption(content,"Local queue unavailable.");}for(int i=0;i<rows("mobileCalls").length();i++){JSONObject r=rows("mobileCalls").optJSONObject(i);if(r==null||ids.contains(r.optString("id"))||(!filter.equals("All")&&!filter.equals(r.optString("direction"))))continue;callCard(r,false);count++;}if(count==0)caption(content,"No matching business calls yet. Enable call access in Settings, then sync after a new assigned-lead call.");}
    void callCard(JSONObject r,boolean local){LinearLayout c=card();text(c,phoneName(r.optString("phone")),17,true);caption(c,r.optString("phone"));text(c,r.optString("direction")+" · "+r.optString("duration","0")+" sec",14,true).setTextColor(PURPLE);long time=r.optLong(local?"started":"startedAt",0);if(time==0)try{time=java.time.Instant.parse(r.optString("startedAt")).toEpochMilli();}catch(Exception ignored){}caption(c,time==0?r.optString("startedAt"):new Date(time).toString());String remote=local?r.optString("remote_id"):r.optString("id");caption(c,(remote.isEmpty()?"Queued on phone":"Synced to CRM")+" · "+(local&&r.optInt("uploaded")==1?"Recording uploaded":!r.optString("uri").isEmpty()?"Recording attached":"No local recording"));if(local&&!r.optString("uri").isEmpty())button(c,"Play local recording",()->play(Uri.parse(r.optString("uri"))));String recording=r.optString("recordingId");if(local)for(int i=0;i<rows("mobileCalls").length();i++){JSONObject server=rows("mobileCalls").optJSONObject(i);if(server!=null&&server.optString("id").equals(remote))recording=server.optString("recordingId");}if(!recording.isEmpty()){final String id=recording;button(c,"Play CRM recording",()->remotePlay(id));}}
    void play(Uri uri){try{if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(this,uri);player.prepare();player.start();new AlertDialog.Builder(this).setTitle("Call recording").setMessage("Playing selected local recording.").setPositiveButton("Stop",(d,w)->stopPlayer()).setOnCancelListener(d->stopPlayer()).show();}catch(Exception e){notice("Recording unavailable. Re-select its file or folder in Settings.");}}
    void stopPlayer(){if(player!=null){player.release();player=null;}clearAudioCache();}
    void clearAudioCache(){java.io.File[] files=getCacheDir().listFiles((dir,name)->name.startsWith("crm-recording-"));if(files!=null)for(java.io.File f:files)f.delete();}
    void remotePlay(String id){work(()->{try{java.io.File audio=SyncEngine.recording(this,id);runOnUiThread(()->play(Uri.fromFile(audio)));}catch(Exception e){failure(e);}});}
    void sync(){work(()->{try{SyncEngine.run(this);loadWorkspace();}catch(Exception e){failure(e);}runOnUiThread(this::render);});}
    void settings(){LinearLayout account=card();try{JSONObject u=new JSONObject(SecureConfig.prefs(this).getString("user","{}"));text(account,u.optString("name"),20,true);caption(account,u.optString("username")+" · "+u.optString("role"));}catch(Exception ignored){}caption(account,"Same account as web CRM. Server automatically determines call ownership.");button(account,"Sign out",()->new AlertDialog.Builder(this).setMessage("Pause sync and remove session and cached workspace? Pending queue remains private to this account on this phone. Original recordings and CRM records are not deleted.").setNegativeButton("Cancel",null).setPositiveButton("Sign out",(d,w)->logout()).show());LinearLayout b=card();text(b,"Business call sync",19,true);caption(b,"No microphone or recording permission. Only existing recordings you select can upload. Obtain participants' consent and follow company policy.");caption(b,"Call-log permission: "+(checkSelfPermission(Manifest.permission.READ_CALL_LOG)==PackageManager.PERMISSION_GRANTED?"Allowed":"Not granted"));button(b,"Grant call-log access",()->requestPermissions(new String[]{Manifest.permission.READ_CALL_LOG},301));caption(b,"Recording folder: "+(SecureConfig.prefs(this).getString("folder","").isEmpty()?"Not selected":"Selected"));button(b,"Choose recording folder",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),302));EditText country=input(b,"Country calling code",SecureConfig.prefs(this).getString("country","91"));CheckBox enabled=new CheckBox(this);enabled.setText("I authorize sync of my assigned business calls and matched recordings");enabled.setChecked(SecureConfig.prefs(this).getBoolean("enabled",false));b.addView(enabled);button(b,"Save sync settings",()->{String code=country.getText().toString().trim();if(!code.matches("[1-9][0-9]{0,2}")){notice("Enter a valid country calling code.");return;}SecureConfig.prefs(this).edit().putString("country",code).putBoolean("enabled",enabled.isChecked()).commit();SyncJob.schedule(this,enabled.isChecked());notice("Saved. Only calls since sign-in are eligible. Android may delay background sync.");});button(b,"Sync now / compatibility check",this::sync);button(b,"Review unmatched recording",this::review);button(b,"Pause sync",()->{SecureConfig.prefs(this).edit().putBoolean("enabled",false).commit();SyncJob.schedule(this,false);render();});syncStatus=text(b,SecureConfig.prefs(this).getString("status","Not yet synced."),13,false);caption(b,"Auto matching needs phone number in filename, close end time and audio duration. Ambiguous recordings need manual review. Only direct audio files in selected folder are scanned.");}
    void logout(){SecureConfig.prefs(this).edit().putBoolean("clickToCall",false).commit();stopService(new Intent(this,CallBridgeService.class));if(busy||SyncEngine.running.get()){SyncJob.schedule(this,false);notice("Current request is stopping. Calling is paused. Retry sign out shortly.");return;}stopPlayer();work(()->{try{SyncEngine.requestApi(this,"/v1/logout","POST",new JSONObject());}catch(Exception ignored){}SecureConfig.logout(this);workspace=new JSONObject();runOnUiThread(this::render);});}
    void review(){try(QueueDb db=new QueueDb(this)){ArrayList<JSONObject> list=SyncEngine.calls(db.getReadableDatabase());if(list.isEmpty()){notice("No pending business recordings. Sync after a new assigned-lead call.");return;}String[] choices=new String[list.size()];for(int i=0;i<list.size();i++)choices[i]=phoneName(list.get(i).optString("phone"))+" · "+new Date(list.get(i).optLong("started"))+" · "+list.get(i).optString("duration")+" sec";new AlertDialog.Builder(this).setTitle("Choose call to attach recording").setItems(choices,(d,w)->{pendingCall=list.get(w).optString("local_id");startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),303);}).show();}catch(Exception e){notice("Unable to open pending recordings.");}}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("pending",pendingCall);}
    @Override protected void onDestroy(){handler.removeCallbacks(update);stopPlayer();super.onDestroy();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);if(request==302){SecureConfig.prefs(this).edit().putString("folder",uri.toString()).commit();render();}if(request==303&&pendingCall!=null){String call=pendingCall;new AlertDialog.Builder(this).setMessage("Confirm this file belongs to selected call. A wrong attachment can disclose a private conversation. Upload next sync?").setNegativeButton("Cancel",null).setPositiveButton("Confirm match",(d,w)->{try(QueueDb db=new QueueDb(this)){ContentValues v=new ContentValues();v.put("uri",uri.toString());v.put("mode","manual");db.getWritableDatabase().update("calls",v,"local_id=? AND uploaded=0",new String[]{call});notice("Match saved. Sync when ready.");}}).show();}}catch(Exception e){notice("File permission not granted. Choose an accessible recording folder.");}}
}
